package com.powercms.cms.delivery;
import com.powercms.cms.publish.SiteCacheWarmupRequested; import com.powercms.cms.site.entity.SiteEntity; import com.powercms.cms.site.repo.SiteRepository; import org.junit.jupiter.api.Test; import org.springframework.boot.context.event.ApplicationReadyEvent; import java.util.*; import static org.mockito.Mockito.*;
class CacheWarmupEventListenerTest { @Test void readyWarmsAllAndIsolatesFailure(){var w=mock(CacheWarmupService.class);var r=mock(SiteRepository.class);var a=new SiteEntity();a.setId(UUID.randomUUID());var b=new SiteEntity();b.setId(UUID.randomUUID());when(r.findAll()).thenReturn(List.of(a,b));doThrow(new RuntimeException()).when(w).trigger(a.getId());new CacheWarmupEventListener(w,r).applicationReady(mock(ApplicationReadyEvent.class));verify(w).trigger(a.getId());verify(w).trigger(b.getId());} @Test void eventFailureDoesNotEscape(){var w=mock(CacheWarmupService.class);doThrow(new RuntimeException()).when(w).trigger(any());new CacheWarmupEventListener(w,mock(SiteRepository.class)).afterCommit(new SiteCacheWarmupRequested(UUID.randomUUID(),"DEPLOY"));}}
